// 个人雇用与雇主经营的有限只读投影；未授权观察者不可枚举他人私账。
#include "estate_employment_internal.hpp"
namespace hanmo::resident {
using namespace estate_employment_detail;
Outcome<std::optional<EstateEmploymentSource>> read_estate_employment_source(const EstateEmploymentContext& x,const StableId& observer,const StableId& id){if(x.phase)return {false,{},common_failure("EmploymentQueryRequiresCommittedClock").error};auto valid=validate_estate_employment(x);if(!valid.ok)return {false,{},valid.error};const auto* c=x.state.contracts.find(id);if(observer!=x.common.state().metadata.player_actor_id||!c||(observer!=c->terms.worker_actor_id&&observer!=c->terms.employer_actor_id))return {true,std::nullopt,{}};auto totals=wage_totals(x,*c);if(!totals.ok)return {false,{},totals.error};auto reserved=actual_reservation(x.common,*c);if(!reserved.ok)return {false,{},reserved.error};EstateEmploymentSource out;out.source_identity=x.common.state().identity;out.observer_actor_id=observer;out.contract_id=id;out.status=c->status;out.offer_fact_id=c->id;out.acceptance_fact_id=c->acceptance_fact_id;out.terminal_fact_id=c->terminal_fact_id;out.obligation_id=c->obligation_id;out.terms=c->terms;out.offered_tick=c->offered_tick;out.accepted_tick=c->accepted_tick;out.through_tick=c->through_tick;out.observed_tick=x.common.tick();out.served_ticks=totals.value.served;out.earned_cash=totals.value.earned;out.paid_cash=totals.value.paid;out.reserved_cash=reserved.value;return {true,std::move(out),{}};}
Outcome<std::optional<EstateEmploymentSource>> EstateEmploymentAccess::estate_employment_source(const StableId& observer,const StableId& id)const{return read_estate_employment_source(context_,observer,id);}
Outcome<std::vector<StableId>> EstateEmploymentAccess::estate_employment_contract_ids(const StableId& observer,Integer offset,Integer limit)const{const auto& x=context_;if(x.phase||offset<0||limit<1||limit>50)return {false,{},common_failure("InvalidEmploymentPage").error};auto valid=validate_estate_employment(x);if(!valid.ok)return {false,{},valid.error};std::vector<StableId> out;if(observer!=x.common.state().metadata.player_actor_id)return {true,std::move(out),{}};Integer seen=0;for(const auto& row:x.state.contracts.rows())if(observer==row.second.terms.worker_actor_id||observer==row.second.terms.employer_actor_id){if(seen++<offset)continue;out.push_back(row.first);if(Integer(out.size())==limit)break;}return {true,std::move(out),{}};}
Outcome<std::vector<EstateEmploymentPolicySource>> EstateEmploymentAccess::estate_employment_policies(const StableId& observer,const StableId& provider)const{
 const auto& x=context_;if(x.phase||x.interaction_catalog!=&meeting_.catalog)return {false,{},common_failure("EmploymentQueryRequiresCommittedClock").error};auto valid=validate_estate_employment(x);if(!valid.ok)return {false,{},valid.error};std::vector<EstateEmploymentPolicySource> out;if(observer!=x.common.state().metadata.player_actor_id)return {true,std::move(out),{}};auto proof=preview_authored_node_source(x.common,meeting_.state,meeting_.catalog,meeting_.access,observer,provider);if(!proof.ok)return {false,{},proof.error};
 for(const auto& row:x.catalog.policies.rows()){
  const auto& p=row.second;const auto* e=x.estates.estates.find(p.estate_id);const auto* definition=x.estate_catalog.estates.find(p.estate_id);if(!e||!definition||definition->place_id!=proof.value.context.place_id)continue;const bool own=e->owner_actor_id==observer,request=e->owner_actor_id==provider;
  if(own){if(p.offer_dialogue_id!=proof.value.dialogue_id||p.offer_node_id!=proof.value.node_id)continue;}else if(request){if(p.provider_offer_dialogue_id!=proof.value.dialogue_id||p.provider_offer_node_id!=proof.value.node_id)continue;auto source=preview_authored_provider_source(x.common,meeting_.state,meeting_.catalog,meeting_.access,observer,provider);if(!source.ok)return {false,{},source.error};}else continue;
  auto terms=freeze_terms(x,p,own?provider:observer);if(!terms.ok)return {false,{},terms.error};const auto& t=terms.value;out.push_back({x.common.state().identity,observer,provider,p.id,p.estate_id,p.job,p.rate_profile,t.wage_numerator,t.wage_denominator,t.service_ticks,p.offer_valid_ticks,t.reservation_cap,t.employer_actor_id,t.worker_actor_id,!own});if(out.size()>50)return {false,{},common_failure("EmploymentPolicyPageLimit").error};
 }return {true,std::move(out),{}};
}
}
